// trainer.cpp — Windows, C++17
// Scan a target process's writable memory for a 32-bit value, narrow the hits
// across two passes, then freeze a chosen address by rewriting it every 50ms.
//
// Usage:  trainer.exe <pid | process.exe>
//
// Build (MSVC):       cl /std:c++17 /EHsc /O2 trainer.cpp
// Build (MinGW/macOS): x86_64-w64-mingw32-g++ -std=c++17 -O2 -static -o trainer.exe trainer.cpp

#define WIN32_LEAN_AND_MEAN
#define NOMINMAX
#include <windows.h>
#include <tlhelp32.h>

#include <algorithm>
#include <atomic>
#include <chrono>
#include <cstdint>
#include <cstdio>
#include <cstring>
#include <iostream>
#include <limits>
#include <string>
#include <thread>
#include <vector>

namespace {

constexpr SIZE_T kChunk = 1 << 20;        // read regions in 1 MiB slices
constexpr uintptr_t kPage = 0x1000;       // x86/x64 Windows page size
constexpr auto kFreezeInterval = std::chrono::milliseconds(50);

DWORD findPidByName(const std::string& name) {
    std::wstring wname(name.size() + 1, L'\0');
    int n = MultiByteToWideChar(CP_UTF8, 0, name.c_str(), -1, wname.data(),
                                static_cast<int>(wname.size()));
    if (n <= 0) return 0;
    wname.resize(n - 1);

    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    if (snap == INVALID_HANDLE_VALUE) return 0;

    PROCESSENTRY32W pe{};
    pe.dwSize = sizeof pe;
    DWORD pid = 0;
    if (Process32FirstW(snap, &pe)) {
        do {
            if (_wcsicmp(pe.szExeFile, wname.c_str()) == 0) {
                pid = pe.th32ProcessID;
                break;
            }
        } while (Process32NextW(snap, &pe));
    }
    CloseHandle(snap);
    return pid;
}

bool isWritable(DWORD protect) {
    if (protect & (PAGE_GUARD | PAGE_NOACCESS)) return false;
    switch (protect & 0xFF) {
        case PAGE_READWRITE:
        case PAGE_WRITECOPY:
        case PAGE_EXECUTE_READWRITE:
        case PAGE_EXECUTE_WRITECOPY:
            return true;
        default:
            return false;
    }
}

// Full scan: every committed writable region, 4-byte aligned.
std::vector<uintptr_t> firstScan(HANDLE proc, int32_t value) {
    SYSTEM_INFO si;
    GetSystemInfo(&si);
    uintptr_t addr = reinterpret_cast<uintptr_t>(si.lpMinimumApplicationAddress);
    const uintptr_t end = reinterpret_cast<uintptr_t>(si.lpMaximumApplicationAddress);

    std::vector<uintptr_t> hits;
    std::vector<uint8_t> buf(kChunk);
    MEMORY_BASIC_INFORMATION mbi;

    while (addr < end &&
           VirtualQueryEx(proc, reinterpret_cast<LPCVOID>(addr), &mbi, sizeof mbi) == sizeof mbi) {
        const uintptr_t base = reinterpret_cast<uintptr_t>(mbi.BaseAddress);
        const uintptr_t regionEnd = base + mbi.RegionSize;

        if (mbi.State == MEM_COMMIT && isWritable(mbi.Protect)) {
            for (uintptr_t p = base; p < regionEnd; p += kChunk) {
                const SIZE_T want = static_cast<SIZE_T>(std::min<uintptr_t>(kChunk, regionEnd - p));
                SIZE_T got = 0;
                // ERROR_PARTIAL_COPY still reports how much was read; use it.
                ReadProcessMemory(proc, reinterpret_cast<LPCVOID>(p), buf.data(), want, &got);
                for (SIZE_T i = 0; i + sizeof(int32_t) <= got; i += sizeof(int32_t)) {
                    int32_t v;
                    std::memcpy(&v, buf.data() + i, sizeof v);
                    if (v == value) hits.push_back(p + i);
                }
            }
        }
        if (regionEnd <= addr) break;  // defensive: never loop on a bogus region
        addr = regionEnd;
    }
    return hits;
}

// Re-read surviving hits and keep those now equal to `value`.
// Hits are sorted, so read one page at a time instead of one syscall per address.
void narrowScan(HANDLE proc, std::vector<uintptr_t>& hits, int32_t value) {
    std::vector<uintptr_t> kept;
    kept.reserve(hits.size());
    uint8_t page[kPage];

    size_t i = 0;
    while (i < hits.size()) {
        const uintptr_t pg = hits[i] & ~(kPage - 1);
        SIZE_T got = 0;
        const bool ok = ReadProcessMemory(proc, reinterpret_cast<LPCVOID>(pg), page, kPage, &got) &&
                        got == kPage;
        for (; i < hits.size() && (hits[i] & ~(kPage - 1)) == pg; ++i) {
            if (!ok) continue;  // page freed or reprotected: drop its hits
            int32_t v;
            std::memcpy(&v, page + (hits[i] - pg), sizeof v);
            if (v == value) kept.push_back(hits[i]);
        }
    }
    hits.swap(kept);
}

int32_t promptInt(const char* msg) {
    for (;;) {
        std::cout << msg << std::flush;
        long long v;
        if (std::cin >> v && v >= std::numeric_limits<int32_t>::min() &&
            v <= std::numeric_limits<int32_t>::max()) {
            std::cin.ignore(std::numeric_limits<std::streamsize>::max(), '\n');
            return static_cast<int32_t>(v);
        }
        std::cin.clear();
        std::cin.ignore(std::numeric_limits<std::streamsize>::max(), '\n');
        std::cout << "  not a valid 32-bit integer\n";
    }
}

void printHits(HANDLE proc, const std::vector<uintptr_t>& hits, size_t limit = 20) {
    const size_t n = std::min(hits.size(), limit);
    for (size_t i = 0; i < n; ++i) {
        int32_t v = 0;
        ReadProcessMemory(proc, reinterpret_cast<LPCVOID>(hits[i]), &v, sizeof v, nullptr);
        std::printf("  [%zu] 0x%p = %d\n", i, reinterpret_cast<void*>(hits[i]), v);
    }
    if (hits.size() > limit) std::printf("  ... %zu more\n", hits.size() - limit);
}

bool processAlive(HANDLE proc) {
    DWORD code = 0;
    return GetExitCodeProcess(proc, &code) && code == STILL_ACTIVE;
}

}  // namespace

int main(int argc, char** argv) {
    if (argc != 2) {
        std::fprintf(stderr, "usage: %s <pid | process.exe>\n", argv[0]);
        return 1;
    }

    char* endp = nullptr;
    DWORD pid = static_cast<DWORD>(std::strtoul(argv[1], &endp, 10));
    if (*endp != '\0' || pid == 0) pid = findPidByName(argv[1]);
    if (pid == 0) {
        std::fprintf(stderr, "process '%s' not found\n", argv[1]);
        return 1;
    }

