                             "rebuild as x64 for full address-space coverage\n");
    }

    std::printf("attached to pid %lu\n", static_cast<unsigned long>(pid));

    // Pass 0: full scan.
    int32_t value = promptInt("initial value: ");
    std::vector<uintptr_t> hits = firstScan(proc, value);
    std::printf("first scan: %zu hits\n", hits.size());
    if (hits.empty()) {
        CloseHandle(proc);
        return 0;
    }

